 useEffect(()=>{
   if(!showHowItWorks)return;
   function closeHowWorkOnOutsidePointer(event){
     if(!event.target.closest('.public-home-nav'))setShowHowItWorks(false);
   }
   function closeHowWorkOnEscape(event){if(event.key==='Escape')setShowHowItWorks(false);}
   document.addEventListener('pointerdown',closeHowWorkOnOutsidePointer);
   document.addEventListener('keydown',closeHowWorkOnEscape);
   return()=>{document.removeEventListener('pointerdown',closeHowWorkOnOutsidePointer);document.removeEventListener('keydown',closeHowWorkOnEscape)};
 },[showHowItWorks]);

